package com.bank.spark.service;

import com.bank.spark.model.Branch;
import com.bank.spark.model.FactPartition;

import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

// Simulates DPP: derive keys from the dimension, prune the fact partitions.
public class DynamicPruner {

    // Static pruning: filter value is a known literal.
    public List<FactPartition> staticPrune(List<FactPartition> fact, String branchLiteral) {
        return fact.stream()
                .filter(p -> p.getBranchId().equals(branchLiteral))
                .collect(Collectors.toList());
    }

    // Dynamic pruning: derive the branch ids from a filtered dimension at runtime.
    public Set<String> deriveKeys(List<Branch> branches, String region) {
        return branches.stream()
                .filter(b -> b.getRegion().equals(region))
                .map(Branch::getBranchId)
                .collect(Collectors.toSet());
    }

    public List<FactPartition> dynamicPrune(List<FactPartition> fact, Set<String> derivedKeys) {
        return fact.stream()
                .filter(p -> derivedKeys.contains(p.getBranchId()))
                .collect(Collectors.toList());
    }

    public long totalBytes(List<FactPartition> parts) {
        return parts.stream().mapToLong(FactPartition::getSizeBytes).sum();
    }
}
