package com.bank.spark;

import com.bank.spark.model.Branch;
import com.bank.spark.model.FactPartition;
import com.bank.spark.service.DynamicPruner;

import java.util.List;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DppDemo {

    private static final Logger log = Logger.getLogger(DppDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DynamicPruner pruner = new DynamicPruner();

        // Large fact table partitioned by branch id.
        List<FactPartition> fact = List.of(
                new FactPartition("BR-MUM", 1_200_000_000L),
                new FactPartition("BR-PUN", 800_000_000L),
                new FactPartition("BR-DEL", 1_000_000_000L),
                new FactPartition("BR-CHE", 700_000_000L)
        );
        long fullScan = pruner.totalBytes(fact);

        // Small dimension: which region each branch belongs to.
        List<Branch> branches = List.of(
                new Branch("BR-MUM", "West"),
                new Branch("BR-PUN", "West"),
                new Branch("BR-DEL", "North"),
                new Branch("BR-CHE", "South")
        );

        // STATIC pruning: WHERE branchId = 'BR-MUM'
        List<FactPartition> staticKept = pruner.staticPrune(fact, "BR-MUM");
        log.info(() -> "STATIC prune (branchId='BR-MUM'): read "
                + (pruner.totalBytes(staticKept) / 1_000_000) + " MB, skipped " + (fact.size() - staticKept.size()) + " partitions");

        // DYNAMIC pruning: WHERE branches.region = 'West' (derived at runtime)
        Set<String> westKeys = pruner.deriveKeys(branches, "West");
        log.info(() -> "DPP derived branch ids from dimension at runtime: " + westKeys);
        List<FactPartition> dppKept = pruner.dynamicPrune(fact, westKeys);
        long dppBytes = pruner.totalBytes(dppKept);
        log.info(() -> "DYNAMIC prune (region='West'): read " + (dppBytes / 1_000_000)
                + " MB across " + dppKept.size() + " partitions, saved "
                + ((fullScan - dppBytes) / 1_000_000) + " MB vs full scan");

        log.info("Static knew the value at plan time; DPP learned it from the dimension at runtime.");
    }
}

